import pytest


def rotl8(x: int, k: int) -> int:
    """Rotate the 8-bit value x left by k bits, wrapping the high bits around.

    x must be in 0..255 and k in 0..7; the result is in 0..255.
    """
    if not 0 <= x <= 255:
        raise ValueError("x must be in 0..255")
    if not 0 <= k <= 7:
        raise ValueError("k must be in 0..7")
    return ((x << k) | (x >> (8 - k))) & 0xFF


def test_rotl8_zero_shift_is_identity() -> None:
    for x in (0, 1, 0x80, 0xA5, 255):
        assert rotl8(x, 0) == x


def test_rotl8_simple_shift() -> None:
    assert rotl8(0b00000001, 1) == 0b00000010
    assert rotl8(0b00000001, 7) == 0b10000000


def test_rotl8_wraps_high_bits() -> None:
    assert rotl8(0b10000000, 1) == 0b00000001
    assert rotl8(0b10000001, 1) == 0b00000011
    assert rotl8(0b11000000, 2) == 0b00000011
    assert rotl8(0b10110001, 4) == 0b00011011


def test_rotl8_known_values() -> None:
    assert rotl8(0xA5, 4) == 0x5A
    assert rotl8(0x0F, 4) == 0xF0
    assert rotl8(0x81, 3) == 0x0C


def test_rotl8_extremes() -> None:
    for k in range(8):
        assert rotl8(0, k) == 0
        assert rotl8(255, k) == 255


def test_rotl8_result_in_range() -> None:
    for x in range(256):
        for k in range(8):
            assert 0 <= rotl8(x, k) <= 255


def test_rotl8_preserves_popcount() -> None:
    for x in range(256):
        for k in range(8):
            assert bin(rotl8(x, k)).count("1") == bin(x).count("1")


def test_rotl8_inverse_rotation() -> None:
    for x in range(256):
        for k in range(8):
            assert rotl8(rotl8(x, k), (8 - k) % 8) == x


def test_rotl8_composition() -> None:
    for x in range(256):
        for a in range(8):
            for b in range(8):
                assert rotl8(rotl8(x, a), b) == rotl8(x, (a + b) % 8)


def test_rotl8_matches_reference() -> None:
    for x in range(256):
        for k in range(8):
            expected = int(format(x, "08b")[k:] + format(x, "08b")[:k], 2)
            assert rotl8(x, k) == expected


def test_rotl8_rejects_out_of_range() -> None:
    with pytest.raises(ValueError):
        rotl8(256, 1)
    with pytest.raises(ValueError):
        rotl8(-1, 1)
    with pytest.raises(ValueError):
        rotl8(1, 8)
    with pytest.raises(ValueError):
        rotl8(1, -1)

